let DeleteExpense = class DeleteExpense {
    constructor(eventEmitter, uow, validator, expenseModel, expenseCategoryModel) {
        this.eventEmitter = eventEmitter;
        this.uow = uow;
        this.validator = validator;
        this.expenseModel = expenseModel;
        this.expenseCategoryModel = expenseCategoryModel;
    }
    async deleteExpense(expenseId, trx) {
        const oldExpense = await this.expenseModel()
            .query()
            .findById(expenseId)
            .withGraphFetched('categories')
            .throwIfNotFound();
        await this.validator.validateNoAssociatedLandedCost(expenseId);
        return this.uow.withTransaction(async (trx) => {
            await this.eventEmitter.emitAsync(events_1.events.expenses.onDeleting, {
                trx,
                oldExpense,
            });
            await this.expenseCategoryModel()
                .query(trx)
                .where('expenseId', expenseId)
                .delete();
            await this.expenseModel().query(trx).findById(expenseId).delete();
            await this.eventEmitter.emitAsync(events_1.events.expenses.onDeleted, {
                expenseId,
                oldExpense,
                trx,
            });
        }, trx);
    }
};

